$ErrorActionPreference = 'Stop'
function Invoke-NativeChecked {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter(ValueFromRemainingArguments = $true)][string[]]$ArgumentList
    )
    & $FilePath @ArgumentList
    $ExitCode = $LASTEXITCODE
    if ($ExitCode -ne 0) { throw "Native command failed with exit code ${ExitCode}: $FilePath $($ArgumentList -join ' ')" }
}
function Invoke-GitChecked {
    param([Parameter(ValueFromRemainingArguments = $true)][string[]]$Arguments)
    & git @Arguments
    $ExitCode = $LASTEXITCODE
    if ($ExitCode -ne 0) { throw "Git command failed with exit code ${ExitCode}: git $($Arguments -join ' ')" }
}
function Invoke-GitCheckIgnore {
    param(
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [int]$ExpectedExitCode = 0
    )
    & git check-ignore @Arguments
    $ExitCode = $LASTEXITCODE
    if ($ExitCode -ne $ExpectedExitCode) { throw "git check-ignore returned unexpected exit code $ExitCode; expected $ExpectedExitCode." }
}
if ($null -eq $PSVersionTable -or $PSVersionTable.PSVersion.Major -lt 7) { throw 'This exercise requires a running PowerShell session with major version 7 or later.' }
if (-not (Get-Command git -CommandType Application -ErrorAction SilentlyContinue)) { throw 'Git is not available. Stop and use the official Git installation documentation.' }
if (-not (Get-Command pwsh -CommandType Application -ErrorAction SilentlyContinue)) { throw 'The pwsh executable is not available. Stop and use the official PowerShell installation documentation.' }
Invoke-NativeChecked -FilePath 'git' -ArgumentList @('--version')
Invoke-NativeChecked -FilePath 'pwsh' -ArgumentList @('--version')
$Practice = Join-Path $HOME 'Project42-GitPractice-20260920'
if (Test-Path -LiteralPath $Practice) { throw "The practice directory already exists: $Practice. Choose a genuinely new empty directory instead." }
New-Item -ItemType Directory -Path $Practice | Out-Null
Set-Location -LiteralPath $Practice
Invoke-GitChecked -Arguments @('init')
